// ?????????????????????????????????????????????????????????????????????????????
// ADVANCED SKILLS EXTENSION v3 - Level-based Unlock & Book Synchronization
// ?????????????????????????????????????????????????????????????????????????????
(function() {
  "use strict";

  // ??ng b? c?u h?nh s?ch k? n?ng
  if (window.JX_ADVANCED && window.JX_ADVANCED.skills) {
    Object.values(window.JX_ADVANCED.skills).forEach(function(sk) {
      if (sk.tier === 120) sk.book = "bk120";
      else if (sk.tier === 150) sk.book = "bk150";
    });
    if (window.JX && window.JX.skills) {
      Object.assign(window.JX.skills, window.JX_ADVANCED.skills);
    }
  }

  // T? ??ng m? kh?a bkOk cho k? n?ng 120 & 150 khi ??t c?p ?? ho?c s? h?u s?ch
  function syncSkillUnlocks() {
    try {
      const JX = window.__JX;
      if (!JX || !JX.S) return;
      const l = JX.S;
      const misc = (l.mats && l.mats.misc) ? l.mats.misc : {};
      const lvl = l.lvl || 1;
      const bkOk = l.bkOk || (l.bkOk = {});

      if (window.JX_ADVANCED && window.JX_ADVANCED.skills) {
        for (const [idStr, sk] of Object.entries(window.JX_ADVANCED.skills)) {
          const id = Number(idStr);
          // 1. ??t ?? c?p ?? m?n ph?i t??ng ?ng -> m? kh?a l?nh ng?
          if (lvl >= sk.req) {
            bkOk[id] = 1;
          }
          // 2. Ho?c c? s?ch k? n?ng t??ng ?ng trong r??ng
          if (sk.book && misc[sk.book] > 0) {
            bkOk[id] = 1;
          }
        }
      }
    } catch(e) {}
  }

  // Ki?m tra ??nh k? v? hook sau khi game n?p xong
  setInterval(syncSkillUnlocks, 1500);

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function() {
      setTimeout(syncSkillUnlocks, 1000);
    });
  } else {
    setTimeout(syncSkillUnlocks, 600);
  }

  console.log("[AdvancedSkills] v3: K? n?ng 120 & 150 t? ??ng m? kh?a theo c?p ?? v? s?ch k? n?ng!");
})();
